int lis(vector<int>& nums) {
    int n = nums.size();
    int ans = 0;

    // There are 2^n possible subsequences
    for (int mask = 0; mask < (1 << n); mask++) {

        vector<int> subseq;

        // Build the subsequence represented by mask
        for (int i = 0; i < n; i++) {
            if (mask & (1 << i)) {
                subseq.push_back(nums[i]);
            }
        }

        // Check whether this subsequence is increasing
        bool increasing = true;

        for (int i = 1; i < subseq.size(); i++) {
            if (subseq[i] <= subseq[i - 1]) {
                increasing = false;
                break;
            }
        }

        if (increasing) {
            ans = max(ans, (int)subseq.size());
        }
    }

    return ans;
}

