### Optimized Code

```cpp
#include <iostream>
#include <string>
#include <vector>
using namespace std;

class Solution {
public:
    string removeDuplicateLetters(string s) {
        int count[26] = {0};
        bool inResult[26] = {false};

        // Step 1: Count frequency of each character
        for (char c : s) {
            count[c - 'a']++;
        }

        string result = "";

        // Step 2: Build result greedily using a monotonic stack pattern
        for (char c : s) {
            // Decrement remaining frequency of current character
            count[c - 'a']--;

            // If character is already in the result, skip it
            if (inResult[c - 'a']) {
                continue;
            }

            // Pop characters that are lexicographically larger than 'c' 
            // if they will appear again later
            while (!result.empty() && result.back() > c && count[result.back() - 'a'] > 0) {
                inResult[result.back() - 'a'] = false;
                result.pop_back();
            }

            // Append current character
            result.push_back(c);
            inResult[c - 'a'] = true;
        }

        return result;
    }
};
```

